from fastapi import FastAPI, Depends, Security
from fastapi.dependencies.utils import get_dependant
from fastapi.security import OAuth2PasswordBearer

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_b():
    return "B"

def dep_c():
    return "C"

def dep_a(b=Depends(dep_b), c=Depends(dep_c)):
    return "A"

# To trigger the bug, we need Security dependencies with scopes.
def dep_b_scoped():
    return "B"

def dep_c_scoped():
    return "C"

def dep_a_scoped(
    b=Security(dep_b_scoped, scopes=["b"]),
    c=Security(dep_c_scoped, scopes=["c"])
):
    return "A"

def test_security_scopes_isolation():
    # Get dependant for dep_a_scoped
    dependant = get_dependant(path="/test", call=dep_a_scoped)

    # dependant.dependencies should contain the dependants for dep_b_scoped and dep_c_scoped
    # Let's find them.
    b_dependant = next(d for d in dependant.dependencies if d.call == dep_b_scoped)
    c_dependant = next(d for d in dependant.dependencies if d.call == dep_c_scoped)

    print(f"B dependant scopes: {b_dependant.security_requirement.scopes}")
    print(f"C dependant scopes: {c_dependant.security_requirement.scopes}")

    assert b_dependant.security_requirement.scopes == ["b"]
    assert c_dependant.security_requirement.scopes == ["c"]

if __name__ == "__main__":
    try:
        test_security_scopes_isolation()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

